-- Seed: the 27 sample events compiled Oct 20, 2026 from public listings and organizer pages.
-- Safe to run more than once. Dates move, so confirm with the organizer before you book.

on conflict (id) do update set
  name = excluded.name, start_date = excluded.start_date, end_date = excluded.end_date, city = excluded.city, country = excluded.country,
  lat = excluded.lat, lng = excluded.lng, metro = excluded.metro, categories = excluded.categories, url = excluded.url, kind = excluded.kind,
  source = excluded.source, venue = excluded.venue, note = excluded.note, status = excluded.status;

delete from public.event_deadlines where event_id in ('gtc27', 'kubecon26');

